<?php
require_once __DIR__.'/../../auth/auth_check.php';require_once __DIR__.'/../../config/database.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['permohonan_id'];$decision=$_POST['keputusan'];$complete=$_POST['kelengkapan'];$note=trim($_POST['catatan']??'');$pdo->prepare('INSERT INTO telaah_permohonan (permohonan_id,petugas_id,kelengkapan_dokumen,catatan,keputusan,created_at) VALUES (?,?,?,?,?,CURRENT_TIMESTAMP)')->execute([$id,$_SESSION['user_id'],$complete,$note,$decision]);$status=['Disetujui'=>'Disetujui','Ditolak'=>'Ditolak','Perlu Perbaikan'=>'Perlu Perbaikan'][''.$decision]??'Dalam Pemeriksaan';$pdo->prepare('UPDATE permohonan SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$status,$id]);$pdo->prepare('INSERT INTO aktivitas_log (user_id,aksi,entitas,entitas_id,detail) VALUES (?,?,?,?,?)')->execute([$_SESSION['user_id'],'Telaah','permohonan',$id,'Keputusan: '.$decision]);header('Location: index.php');exit;}
$rows=$pdo->query('SELECT p.*,t.keputusan,t.kelengkapan_dokumen,t.catatan FROM permohonan p LEFT JOIN telaah_permohonan t ON t.id=(SELECT MAX(id) FROM telaah_permohonan WHERE permohonan_id=p.id) ORDER BY p.created_at DESC')->fetchAll();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Telaah Permohonan | SICERDAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/../../layouts/sidebar.php';?><div class="main-wrapper"><?php include __DIR__.'/../../layouts/navbar.php';?><main class="content"><div class="page-heading"><div><p>Pemeriksaan Permohonan</p><h1>Telaah Permohonan</h1></div></div><div class="panel table-panel"><div class="table-responsive"><table class="table sicerdas-table"><thead><tr><th>Nomor</th><th>Pemohon</th><th>Status</th><th>Kelengkapan</th><th>Keputusan</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nomor_permohonan'])?></td><td><?=htmlspecialchars($r['nama_pemohon'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><?=htmlspecialchars($r['kelengkapan_dokumen']??'Belum ditelaah')?></td><td><?=htmlspecialchars($r['keputusan']??'Menunggu')?></td><td><button class="btn btn-sm btn-detail" data-bs-toggle="modal" data-bs-target="#modal<?=$r['id']?>">Telaah</button></td></tr><div class="modal fade" id="modal<?=$r['id']?>"><div class="modal-dialog"><form method="post" class="modal-content"><div class="modal-header"><h5 class="modal-title">Telaah <?=htmlspecialchars($r['nomor_permohonan'])?></h5></div><div class="modal-body"><input type="hidden" name="permohonan_id" value="<?=$r['id']?>"><label class="form-label">Kelengkapan Dokumen</label><select class="form-select mb-2" name="kelengkapan"><option>Lengkap</option><option>Tidak Lengkap</option></select><label class="form-label">Keputusan</label><select class="form-select mb-2" name="keputusan"><option>Disetujui</option><option>Ditolak</option><option>Perlu Perbaikan</option></select><label class="form-label">Catatan</label><textarea class="form-control" name="catatan" rows="3"><?=htmlspecialchars($r['catatan']??'')?></textarea></div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal" type="button">Batal</button><button class="btn btn-orange">Simpan Telaah</button></div></form></div></div><?php endforeach;if(!$rows):?><tr><td colspan="6" class="text-center py-4">Belum ada permohonan.</td></tr><?php endif?></tbody></table></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
